/* Docloom — 单文档结构化编辑器
   设计令牌：低密度（spacious）、专业工具、克制用色 */

:root {
  --bg: #eef0f4;
  --pane: #ffffff;
  --line: #e3e6ec;
  --line-strong: #cdd2dc;
  --ink: #1c2430;
  --ink-2: #5b6572;
  --ink-3: #8a94a3;
  --accent: #2f6bde;
  --accent-soft: #e8effc;
  --accent-line: #b9cdf3;
  --danger: #c2372c;
  --danger-soft: #fdeeec;
  --warn: #9a5b0a;
  --warn-soft: #fdf4e3;
  --ok: #23764a;
  --ok-soft: #e7f5ec;
  --radius: 8px;
  --head-h: 44px;
  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
  --mono: Consolas, "SFMono-Regular", Menlo, monospace;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.6;
  color: var(--ink);
  background: var(--bg);
  overflow: hidden;
}

.sr-only {
  position: absolute; width: 1px; height: 1px;
  margin: -1px; padding: 0; border: 0;
  clip: rect(0 0 0 0); overflow: hidden; white-space: nowrap;
}

/* ---------- 顶部工具带 ---------- */
.topbar {
  height: var(--head-h);
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 14px;
  background: var(--pane);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: baseline; gap: 7px; white-space: nowrap; }
.brand-mark { color: var(--accent); font-size: 15px; }
.brand-name { font-weight: 700; letter-spacing: .2px; }
.brand-sub { color: var(--ink-3); font-size: 12px; }
.doc-title-wrap { flex: 1 1 auto; min-width: 120px; }
.doc-title {
  width: 100%;
  max-width: 520px;
  display: block;
  font: inherit;
  font-size: 15px;
  font-weight: 600;
  color: var(--ink);
  padding: 5px 10px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: transparent;
}
.doc-title:hover { border-color: var(--line); }
.doc-title:focus { outline: none; border-color: var(--accent-line); background: var(--pane); box-shadow: 0 0 0 3px var(--accent-soft); }
.topbar-actions { display: flex; align-items: center; gap: 8px; white-space: nowrap; }
.edit-state { color: var(--ink-3); font-size: 12px; margin-right: 4px; }
.tbtn {
  font: inherit; font-size: 13px;
  color: var(--ink-2);
  background: var(--pane);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  padding: 4px 11px;
  cursor: pointer;
}
.tbtn:hover:not(:disabled) { border-color: var(--accent); color: var(--accent); }
.tbtn:disabled { opacity: .42; cursor: not-allowed; }
.tbtn-report .badge { pointer-events: none; }
.badge {
  display: inline-block;
  font-size: 12px;
  padding: 2px 9px;
  border-radius: 999px;
  background: var(--ok-soft);
  color: var(--ok);
}
.badge.has-issues { background: var(--warn-soft); color: var(--warn); }

/* ---------- 工作台三栏 ---------- */
.workbench {
  height: calc(100% - var(--head-h));
  display: grid;
  grid-template-columns: 300px minmax(360px, 1fr) minmax(400px, 1fr);
}
.pane { display: flex; flex-direction: column; min-width: 0; min-height: 0; background: var(--pane); }
.pane + .pane { border-left: 1px solid var(--line); }
.pane-outline { background: #f7f8fb; }
.pane-head {
  flex: 0 0 auto;
  height: 40px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  border-bottom: 1px solid var(--line);
}
.pane-name { font-size: 11px; font-weight: 700; letter-spacing: .14em; color: var(--ink-3); }
.pane-meta { font-size: 12px; color: var(--ink-3); }
.pv-sync-hint { margin-left: auto; }
.pv-sync-hint::before { content: "●"; color: var(--ok); font-size: 8px; vertical-align: 2px; margin-right: 5px; }

/* ---------- 大纲 ---------- */
.outline-tree { flex: 1 1 auto; overflow: auto; padding: 10px 8px 16px; }
.ol-item { list-style: none; }
.ol-row {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 2px 0 2px calc((var(--d) - 1) * 18px);
  padding: 4px 6px 4px 8px;
  border-radius: 7px;
  border: 1px solid transparent;
